// Checks if vector v starts with prefix p
fn has_prefix(v: &Vec<char>, p: &Vec<char>) -> bool {
    if p.is_empty() {
        return true;
    }
    if v.len() < p.len() {
        return false;
    }
    for i in 0..p.len() {
        if v[i] != p[i] {
            return false;
        }
    }
    true
}

// Filters list xs, keeping only sequences that start with prefix p,
// preserving relative order.
fn filter_by_prefix(xs: Vec<Vec<char>>, p: Vec<char>) -> Vec<Vec<char>> {
    let mut filtered = Vec::new();
    for seq in xs {
        if has_prefix(&seq, &p) {
            filtered.push(seq);
        }
    }
    filtered
}